202:/** A box whose faces show whole-pixel crops of one tile, so any size keeps square texels. */
203:function pixBox(w: number, h: number, d: number, tw: number, th: number) {
204:  const geo = new BoxGeometry(w, h, d);
205:  const uv = geo.getAttribute("uv");
206:  const faces: [number, number][] = [
207:    [d, h],
208:    [d, h],
209:    [w, d],
210:    [w, d],
211:    [w, h],
212:    [w, h],
213:  ];
214:  faces.forEach(([fw, fh], f) => {
215:    const nu = Math.min(tw, Math.max(1, Math.round(fw / TEXEL)));
216:    const nv = Math.min(th, Math.max(1, Math.round(fh / TEXEL)));
217:    for (let i = 0; i < 4; i++) {
218:      const k = f * 4 + i;
219:      uv.setXY(k, uv.getX(k) * (nu / tw), uv.getY(k) * (nv / th));
220:    }
221:  });
222:  return geo;
223:}
