231:/** A pixel-staircase outline: columns `u` wide, each spanning [bottom, top] in units of `unit`, traced round. */
232:function stepped(cols: [number, number][], u: number, unit: number, x0 = 0): [number, number, "sharp"][] {
233:  const pts: [number, number][] = [];
234:  const push = (x: number, y: number) => {
235:    const last = pts[pts.length - 1];
236:    if (!last || Math.abs(last[0] - x) > 1e-9 || Math.abs(last[1] - y) > 1e-9) pts.push([x, y]);
237:  };
238:  cols.forEach(([bot], i) => {
239:    push((i + x0) * u, bot * unit);
240:    push((i + 1 + x0) * u, bot * unit);
241:  });
242:  for (let i = cols.length - 1; i >= 0; i--) {
243:    push((i + 1 + x0) * u, cols[i][1] * unit);
244:    push((i + x0) * u, cols[i][1] * unit);
245:  }
246:  return pts.map(([x, y]) => [x, y, "sharp"]);
247:}
248:
249:/** Piecewise smoothstep through `[t, value]` keys. */
250:function keyed(keys: [number, number][], t: number) {
251:  if (t <= keys[0][0]) return keys[0][1];
252:  for (let i = 0; i < keys.length - 1; i++) {
253:    const [ta, va] = keys[i];
254:    const [tb, vb] = keys[i + 1];
255:    if (t <= tb) {
256:      const k = (t - ta) / (tb - ta);
257:      return va + (vb - va) * k * k * (3 - 2 * k);
258:    }
259:  }
260:  return keys[keys.length - 1][1];
261:}
